const t="IgpbVWoTzeQ",n="IgpbVWoTzeQ",e="You Don’t Need to Be Ready to Start | A1 English Shadowing",i="English Shadowing",s="A1",r=648,a="auto",o=JSON.parse(`[{"start":0,"end":2.16,"text":"Start before you are ready.","words":[["Start",0],["before",0.52],["you",0.96],["are",1.16],["ready.",1.28]],"ipa":"/stɑrt bɪˈfɔr ju ɑr ˈrɛdi/","vi":"Hãy bắt đầu trước khi bạn sẵn sàng."},{"start":2.16,"end":6.88,"text":"This idea sounds simple, but it can change your life.","words":[["This",2.16],["idea",2.52],["sounds",3.08],["simple,",3.56],["but",4.64],["it",4.96],["can",5.08],["change",5.32],["your",5.8],["life.",5.92]],"ipa":"/ðɪs aɪˈdiə saʊndz ˈsɪmpəl bʌt ɪt kæn tʃeɪndʒ jɔr laɪf/","vi":"Ý tưởng này nghe có vẻ đơn giản nhưng nó có thể thay đổi cuộc đời bạn."},{"start":6.88,"end":9.68,"text":"Many people wait for the perfect time.","words":[["Many",6.88],["people",7.16],["wait",7.64],["for",8],["the",8.12],["perfect",8.24],["time.",8.72]],"ipa":"/ˈmɛni ˈpipəl weɪt fɔr ðə pərˈfɛkt taɪm/","vi":"Nhiều người chờ đợi thời điểm hoàn hảo."},{"start":9.68,"end":14.56,"text":"They wait until they feel strong, smart, and confident.","words":[["They",9.68],["wait",9.92],["until",10.2],["they",10.52],["feel",10.68],["strong,",11.04],["smart,",12.36],["and",13.04],["confident.",13.32]],"ipa":"/ðeɪ weɪt ənˈtɪl ðeɪ fil strɔŋ smɑrt ənd ˈkɑnfədənt/","vi":"Họ chờ đợi cho đến khi họ cảm thấy mạnh mẽ, thông minh và tự tin."},{"start":14.56,"end":19,"text":"They think, \\"I will start when I am ready.\\"","words":[["They",14.56],["think,",14.76],["\\"I",16.08],["will",16.32],["start",16.52],["when",17.04],["I",17.24],["am",17.48],["ready.\\"",17.76]],"ipa":"/ðeɪ θɪŋk aɪ wɪl stɑrt wɛn aɪ æm ˈrɛdi/","vi":"Họ nghĩ: “Tôi sẽ bắt đầu khi tôi sẵn sàng”."},{"start":19,"end":23.08,"text":"But the truth is that time may never come.","words":[["But",19],["the",19.24],["truth",19.36],["is",19.88],["that",20.92],["time",21.2],["may",21.6],["never",21.8],["come.",22.12]],"ipa":"/bʌt ðə truθ ɪz ðæt taɪm meɪ ˈnɛvər kʌm/","vi":"Nhưng sự thật là thời gian có thể không bao giờ đến."},{"start":23.08,"end":25.68,"text":"You may never feel fully ready.","words":[["You",23.08],["may",23.28],["never",23.48],["feel",23.96],["fully",24.4],["ready.",24.76]],"ipa":"/ju meɪ ˈnɛvər fil ˈfʊli ˈrɛdi/","vi":"Bạn có thể không bao giờ cảm thấy hoàn toàn sẵn sàng."},{"start":25.68,"end":28.28,"text":"There is always something missing.","words":[["There",25.68],["is",25.92],["always",26.24],["something",26.8],["missing.",27.24]],"ipa":"/ðɛr ɪz ˈɔlˌweɪz ˈsʌmθɪŋ ˈmɪsɪŋ/","vi":"Luôn luôn có một cái gì đó thiếu."},{"start":28.28,"end":31.16,"text":"Maybe you think you do not have enough time.","words":[["Maybe",28.28],["you",28.68],["think",28.72],["you",29.04],["do",29.12],["not",29.28],["have",29.56],["enough",29.8],["time.",30.12]],"ipa":"/ˈmeɪbi ju θɪŋk ju du nɑt hæv ɪˈnʌf taɪm/","vi":"Có lẽ bạn nghĩ rằng bạn không có đủ thời gian."},{"start":31.16,"end":33.72,"text":"Maybe you think you are not good enough.","words":[["Maybe",31.16],["you",31.52],["think",31.64],["you",31.92],["are",32.04],["not",32.16],["good",32.48],["enough.",32.64]],"ipa":"/ˈmeɪbi ju θɪŋk ju ɑr nɑt ɡʊd ɪˈnʌf/","vi":"Có lẽ bạn nghĩ rằng bạn không đủ tốt."},{"start":33.72,"end":35.64,"text":"Maybe you feel afraid.","words":[["Maybe",33.72],["you",34.08],["feel",34.24],["afraid.",34.52]],"ipa":"/ˈmeɪbi ju fil əˈfreɪd/","vi":"Có lẽ bạn cảm thấy sợ hãi."},{"start":35.64,"end":37.72,"text":"These feelings are normal.","words":[["These",35.64],["feelings",35.96],["are",36.48],["normal.",36.6]],"ipa":"/ðiz ˈfilɪŋz ɑr ˈnɔrməl/","vi":"Những cảm giác này là bình thường."},{"start":37.72,"end":40.88,"text":"Everyone feels this way at some point.","words":[["Everyone",37.72],["feels",38.32],["this",38.84],["way",39.08],["at",39.36],["some",39.6],["point.",39.84]],"ipa":"/ˈɛvriˌwʌn filz ðɪs weɪ æt sʌm pɔɪnt/","vi":"Mọi người đều cảm thấy như vậy vào một lúc nào đó."},{"start":40.88,"end":45.28,"text":"But if you always wait, you will stay in the same place.","words":[["But",40.88],["if",41.12],["you",41.28],["always",41.48],["wait,",42],["you",42.88],["will",43],["stay",43.12],["in",43.48],["the",43.6],["same",43.72],["place.",44.16]],"ipa":"/bʌt ɪf ju ˈɔlˌweɪz weɪt ju wɪl steɪ ɪn ðə seɪm pleɪs/","vi":"Nhưng nếu bạn luôn chờ đợi, bạn sẽ ở yên một chỗ."},{"start":45.28,"end":47.8,"text":"Your life will not move forward.","words":[["Your",45.28],["life",45.52],["will",46.12],["not",46.24],["move",46.56],["forward.",46.84]],"ipa":"/jɔr laɪf wɪl nɑt muv ˈfɔrwərd/","vi":"Cuộc sống của bạn sẽ không tiến về phía trước."},{"start":47.8,"end":52.16,"text":"You will only watch others grow while you stay still.","words":[["You",47.8],["will",48.04],["only",48.28],["watch",48.72],["others",49.04],["grow",49.36],["while",50.32],["you",50.56],["stay",50.72],["still.",51.08]],"ipa":"/ju wɪl ˈoʊnli wɑtʃ ˈʌðərz ɡroʊ waɪl ju steɪ stɪl/","vi":"Bạn sẽ chỉ nhìn người khác trưởng thành trong khi bạn vẫn đứng yên."},{"start":52.16,"end":56.4,"text":"When you start before you are ready, you take a small step.","words":[["When",52.16],["you",52.36],["start",52.48],["before",52.88],["you",53.32],["are",53.48],["ready,",53.64],["you",54.36],["take",54.56],["a",54.84],["small",54.88],["step.",55.4]],"ipa":"/wɛn ju stɑrt bɪˈfɔr ju ɑr ˈrɛdi ju teɪk ə smɔl stɛp/","vi":"Khi bạn bắt đầu trước khi sẵn sàng, bạn sẽ thực hiện một bước nhỏ."},{"start":56.4,"end":58.68,"text":"It does not have to be big.","words":[["It",56.4],["does",56.56],["not",56.76],["have",57.12],["to",57.36],["be",57.48],["big.",57.64]],"ipa":"/ɪt dʌz nɑt hæv tu bi bɪɡ/","vi":"Nó không cần phải lớn."},{"start":58.68,"end":60.64,"text":"It can be very small.","words":[["It",58.68],["can",58.8],["be",58.96],["very",59.16],["small.",59.6]],"ipa":"/ɪt kæn bi ˈvɛri smɔl/","vi":"Nó có thể rất nhỏ."},{"start":60.64,"end":62.8,"text":"Maybe you want to learn English.","words":[["Maybe",60.64],["you",61.04],["want",61.12],["to",61.28],["learn",61.36],["English.",61.64]],"ipa":"/ˈmeɪbi ju wɑnt tu lɝn ˈɪŋɡlɪʃ/","vi":"Có lẽ bạn muốn học tiếng Anh."},{"start":62.8,"end":66.36,"text":"You can start by reading one simple sentence.","words":[["You",62.8],["can",62.92],["start",63.08],["by",63.44],["reading",63.72],["one",64.36],["simple",64.68],["sentence.",65.12]],"ipa":"/ju kæn stɑrt baɪ ˈridɪŋ wʌn ˈsɪmpəl ˈsɛntəns/","vi":"Bạn có thể bắt đầu bằng cách đọc một câu đơn giản."},{"start":66.36,"end":68.48,"text":"Maybe you want to make a video.","words":[["Maybe",66.36],["you",66.68],["want",66.76],["to",66.96],["make",67.04],["a",67.24],["video.",67.32]],"ipa":"/ˈmeɪbi ju wɑnt tu meɪk ə ˈvɪdioʊ/","vi":"Có lẽ bạn muốn làm một video."},{"start":68.48,"end":72.04,"text":"You can start by recording one short clip.","words":[["You",68.48],["can",68.6],["start",68.8],["by",69.2],["recording",69.44],["one",70.28],["short",70.68],["clip.",71.12]],"ipa":"/ju kæn stɑrt baɪ rəˈkɔrdɪŋ wʌn ʃɔrt klɪp/","vi":"Bạn có thể bắt đầu bằng cách ghi một đoạn clip ngắn."},{"start":72.04,"end":74.16,"text":"Maybe you want to exercise.","words":[["Maybe",72.04],["you",72.4],["want",72.48],["to",72.64],["exercise.",72.72]],"ipa":"/ˈmeɪbi ju wɑnt tu ˈɛksərˌsaɪz/","vi":"Có lẽ bạn muốn tập thể dục."},{"start":74.16,"end":76.36,"text":"You can start with 5 minutes.","words":[["You",74.16],["can",74.32],["start",74.52],["with",74.8],["5",75.04],["minutes.",75.4]],"ipa":"/ju kæn stɑrt wɪð ˈmɪnəts/","vi":"Bạn có thể bắt đầu với 5 phút."},{"start":76.36,"end":79.72,"text":"The first step is always the hardest.","words":[["The",76.36],["first",76.6],["step",77],["is",77.56],["always",77.96],["the",78.4],["hardest.",78.52]],"ipa":"/ðə fɝst stɛp ɪz ˈɔlˌweɪz ðə ˈhɑrdəst/","vi":"Bước đầu tiên bao giờ cũng khó khăn nhất."},{"start":79.72,"end":82.28,"text":"Your heart may beat fast.","words":[["Your",79.72],["heart",79.96],["may",80.56],["beat",80.8],["fast.",81.16]],"ipa":"/jɔr hɑrt meɪ bit fæst/","vi":"Tim bạn có thể đập nhanh."},{"start":82.28,"end":84.36,"text":"Your hands may shake.","words":[["Your",82.28],["hands",82.52],["may",83.08],["shake.",83.32]],"ipa":"/jɔr hændz meɪ ʃeɪk/","vi":"Tay bạn có thể run."},{"start":84.36,"end":87.16,"text":"Your mind may say, \\"Stop.","words":[["Your",84.36],["mind",84.6],["may",85.04],["say,",85.24],["\\"Stop.",86.04]],"ipa":"/jɔr maɪnd meɪ seɪ stɑp/","vi":"Tâm trí bạn có thể nói, \\"Dừng lại."},{"start":87.16,"end":88.92,"text":"You are not ready.\\"","words":[["You",87.16],["are",87.32],["not",87.44],["ready.\\"",87.76]],"ipa":"/ju ɑr nɑt ˈrɛdi/","vi":"Bạn chưa sẵn sàng.\\""},{"start":88.92,"end":92.36,"text":"But if you keep going, something will change.","words":[["But",88.92],["if",89.16],["you",89.28],["keep",89.4],["going,",89.72],["something",90.52],["will",91],["change.",91.16]],"ipa":"/bʌt ɪf ju kip ˈɡoʊɪŋ ˈsʌmθɪŋ wɪl tʃeɪndʒ/","vi":"Nhưng nếu bạn tiếp tục, sẽ có điều gì đó thay đổi."},{"start":92.36,"end":95.12,"text":"You will feel a little stronger.","words":[["You",92.36],["will",92.48],["feel",92.64],["a",93.44],["little",93.56],["stronger.",93.96]],"ipa":"/ju wɪl fil ə ˈlɪtəl ˈstrɔŋər/","vi":"Bạn sẽ cảm thấy mạnh mẽ hơn một chút."},{"start":95.12,"end":97.6,"text":"You will feel a little more brave.","words":[["You",95.12],["will",95.28],["feel",95.44],["a",95.84],["little",95.92],["more",96.24],["brave.",96.44]],"ipa":"/ju wɪl fil ə ˈlɪtəl mɔr breɪv/","vi":"Bạn sẽ cảm thấy dũng cảm hơn một chút."},{"start":97.6,"end":102.04,"text":"And that small step will become the start of something bigger.","words":[["And",97.6],["that",98.12],["small",98.4],["step",98.96],["will",99.44],["become",99.56],["the",100.08],["start",100.2],["of",100.52],["something",100.64],["bigger.",101.08]],"ipa":"/ənd ðæt smɔl stɛp wɪl bɪˈkʌm ðə stɑrt ʌv ˈsʌmθɪŋ ˈbɪɡər/","vi":"Và bước đi nhỏ đó sẽ trở thành khởi đầu cho một điều gì đó lớn lao hơn."},{"start":102.04,"end":105.8,"text":"People often think that confidence comes first.","words":[["People",102.04],["often",102.48],["think",102.92],["that",103.36],["confidence",103.6],["comes",104.28],["first.",104.72]],"ipa":"/ˈpipəl ˈɔfən θɪŋk ðæt ˈkɑnfədəns kʌmz fɝst/","vi":"Mọi người thường nghĩ rằng sự tự tin đến trước."},{"start":105.8,"end":110.52,"text":"They think, \\"When I feel confident, I will act.\\"","words":[["They",105.8],["think,",106.04],["\\"When",106.96],["I",107.16],["feel",107.32],["confident,",107.8],["I",108.8],["will",108.96],["act.\\"",109.24]],"ipa":"/ðeɪ θɪŋk wɛn aɪ fil ˈkɑnfədənt aɪ wɪl ækt/","vi":"Họ nghĩ: “Khi tôi cảm thấy tự tin, tôi sẽ hành động”."},{"start":110.52,"end":112.56,"text":"But this is not true.","words":[["But",110.52],["this",110.84],["is",111.08],["not",111.24],["true.",111.56]],"ipa":"/bʌt ðɪs ɪz nɑt tru/","vi":"Nhưng điều này không đúng."},{"start":112.56,"end":115.24,"text":"Confidence comes after action.","words":[["Confidence",112.56],["comes",113.36],["after",113.8],["action.",114.2]],"ipa":"/ˈkɑnfədəns kʌmz ˈæftər ˈækʃən/","vi":"Sự tự tin đến sau hành động."},{"start":115.24,"end":121,"text":"When you do something again and again, you start to feel more comfortable.","words":[["When",115.24],["you",115.44],["do",115.56],["something",115.84],["again",116.32],["and",117.16],["again,",117.4],["you",118.56],["start",118.72],["to",119],["feel",119.12],["more",119.52],["comfortable.",119.76]],"ipa":"/wɛn ju du ˈsʌmθɪŋ əˈɡɛn ənd əˈɡɛn ju stɑrt tu fil mɔr ˈkʌmfərtəbəl/","vi":"Khi bạn làm đi làm lại điều gì đó, bạn sẽ bắt đầu cảm thấy thoải mái hơn."},{"start":121,"end":124.36,"text":"You make mistakes, but you learn from them.","words":[["You",121],["make",121.2],["mistakes,",121.48],["but",122.6],["you",122.88],["learn",123.04],["from",123.36],["them.",123.52]],"ipa":"/ju meɪk mɪˈsteɪks bʌt ju lɝn frʌm ðɛm/","vi":"Bạn mắc sai lầm, nhưng bạn học được từ chúng."},{"start":124.36,"end":127.48,"text":"You see that you can do more than you thought.","words":[["You",124.36],["see",124.52],["that",124.8],["you",125],["can",125.12],["do",125.32],["more",125.6],["than",125.96],["you",126.16],["thought.",126.32]],"ipa":"/ju si ðæt ju kæn du mɔr ðæn ju θɔt/","vi":"Bạn thấy rằng bạn có thể làm được nhiều hơn bạn nghĩ."},{"start":127.48,"end":131.04,"text":"Slowly, your fear becomes smaller.","words":[["Slowly,",127.48],["your",128.6],["fear",128.88],["becomes",129.36],["smaller.",129.92]],"ipa":"/ˈsloʊli jɔr fɪr bɪˈkʌmz ˈsmɔlər/","vi":"Dần dần, nỗi sợ hãi của bạn trở nên nhỏ hơn."},{"start":131.04,"end":134,"text":"Slowly, your confidence grows.","words":[["Slowly,",131.04],["your",131.96],["confidence",132.16],["grows.",132.84]],"ipa":"/ˈsloʊli jɔr ˈkɑnfədəns ɡroʊz/","vi":"Dần dần, sự tự tin của bạn tăng lên."},{"start":134,"end":139.4,"text":"If you wait for confidence before you start, you may wait forever.","words":[["If",134],["you",134.2],["wait",134.44],["for",134.76],["confidence",134.92],["before",135.6],["you",135.96],["start,",136.08],["you",137.12],["may",137.44],["wait",137.72],["forever.",138.24]],"ipa":"/ɪf ju weɪt fɔr ˈkɑnfədəns bɪˈfɔr ju stɑrt ju meɪ weɪt fərˈɛvər/","vi":"Nếu bạn chờ đợi sự tự tin trước khi bắt đầu, bạn có thể phải chờ đợi mãi mãi."},{"start":139.4,"end":143.28,"text":"But if you act first, confidence will follow you.","words":[["But",139.4],["if",139.64],["you",139.8],["act",139.96],["first,",140.32],["confidence",141.16],["will",141.88],["follow",142.04],["you.",142.48]],"ipa":"/bʌt ɪf ju ækt fɝst ˈkɑnfədəns wɪl ˈfɑloʊ ju/","vi":"Nhưng nếu bạn hành động trước, sự tự tin sẽ theo sau bạn."},{"start":143.28,"end":146.52,"text":"Mistakes are also very important.","words":[["Mistakes",143.28],["are",144],["also",144.2],["very",145],["important.",145.4]],"ipa":"/mɪˈsteɪks ɑr ˈɔlsoʊ ˈvɛri ˌɪmˈpɔrtənt/","vi":"Những sai lầm cũng rất quan trọng."},{"start":146.52,"end":149.4,"text":"Many people are afraid of mistakes.","words":[["Many",146.52],["people",146.84],["are",147.32],["afraid",147.48],["of",148],["mistakes.",148.12]],"ipa":"/ˈmɛni ˈpipəl ɑr əˈfreɪd ʌv mɪˈsteɪks/","vi":"Nhiều người sợ mắc sai lầm."},{"start":149.4,"end":154.64,"text":"They want everything to be perfect, but perfection is not real.","words":[["They",149.4],["want",149.56],["everything",149.96],["to",150.52],["be",150.64],["perfect,",150.8],["but",152.2],["perfection",152.48],["is",153.2],["not",153.36],["real.",153.68]],"ipa":"/ðeɪ wɑnt ˈɛvriˌθɪŋ tu bi pərˈfɛkt bʌt pərˈfɛkʃən ɪz nɑt ril/","vi":"Họ muốn mọi thứ phải hoàn hảo, nhưng sự hoàn hảo không có thật."},{"start":154.64,"end":158.64,"text":"When you try something new, you will make mistakes.","words":[["When",154.64],["you",154.84],["try",154.96],["something",155.28],["new,",155.8],["you",156.72],["will",156.92],["make",157.08],["mistakes.",157.4]],"ipa":"/wɛn ju traɪ ˈsʌmθɪŋ nu ju wɪl meɪk mɪˈsteɪks/","vi":"Khi bạn thử một cái gì đó mới, bạn sẽ mắc sai lầm."},{"start":158.64,"end":160.24,"text":"This is normal.","words":[["This",158.64],["is",158.92],["normal.",159.12]],"ipa":"/ðɪs ɪz ˈnɔrməl/","vi":"Điều này là bình thường."},{"start":160.24,"end":162.12,"text":"This is how you learn.","words":[["This",160.24],["is",160.52],["how",160.72],["you",160.96],["learn.",161.12]],"ipa":"/ðɪs ɪz haʊ ju lɝn/","vi":"Đây là cách bạn học."},{"start":162.12,"end":166.28,"text":"A child does not walk perfectly the first time.","words":[["A",162.12],["child",162.24],["does",162.76],["not",162.96],["walk",163.32],["perfectly",163.76],["the",164.76],["first",164.88],["time.",165.32]],"ipa":"/ə tʃaɪld dʌz nɑt wɔk ˈpɝfəktli ðə fɝst taɪm/","vi":"Một đứa trẻ bước đi không hoàn hảo trong lần đầu tiên."},{"start":166.28,"end":169.24,"text":"A child falls many times.","words":[["A",166.28],["child",166.4],["falls",167.04],["many",167.64],["times.",168]],"ipa":"/ə tʃaɪld fɔlz ˈmɛni taɪmz/","vi":"Một đứa trẻ bị ngã nhiều lần."},{"start":169.24,"end":171.68,"text":"But the child keeps trying.","words":[["But",169.24],["the",169.48],["child",169.64],["keeps",170.2],["trying.",170.56]],"ipa":"/bʌt ðə tʃaɪld kips ˈtraɪɪŋ/","vi":"Nhưng đứa trẻ vẫn tiếp tục cố gắng."},{"start":171.68,"end":177.6,"text":"And one day, the child can walk, then run, then jump.","words":[["And",171.68],["one",171.96],["day,",172.24],["the",173],["child",173.12],["can",173.6],["walk,",173.8],["then",174.8],["run,",175.12],["then",176.08],["jump.",176.52]],"ipa":"/ənd wʌn deɪ ðə tʃaɪld kæn wɔk ðɛn rʌn ðɛn dʒʌmp/","vi":"Và một ngày nào đó, đứa trẻ có thể đi, rồi chạy, rồi nhảy."},{"start":177.6,"end":182.88,"text":"If the child was afraid to fall, the child would never learn to walk.","words":[["If",177.6],["the",177.8],["child",177.92],["was",178.44],["afraid",178.56],["to",179.04],["fall,",179.16],["the",180.16],["child",180.32],["would",180.84],["never",181.04],["learn",181.44],["to",181.72],["walk.",181.88]],"ipa":"/ɪf ðə tʃaɪld wɑz əˈfreɪd tu fɔl ðə tʃaɪld wʊd ˈnɛvər lɝn tu wɔk/","vi":"Nếu trẻ sợ ngã thì trẻ sẽ không bao giờ tập đi được."},{"start":182.88,"end":186.96,"text":"In the same way, you must accept mistakes.","words":[["In",182.88],["the",183.04],["same",183.16],["way,",183.64],["you",184.68],["must",184.88],["accept",185.24],["mistakes.",185.76]],"ipa":"/ɪn ðə seɪm weɪ ju mʌst ækˈsɛpt mɪˈsteɪks/","vi":"Tương tự như vậy, bạn phải chấp nhận sai lầm."},{"start":186.96,"end":188.84,"text":"They are not your enemy.","words":[["They",186.96],["are",187.16],["not",187.28],["your",187.6],["enemy.",187.84]],"ipa":"/ðeɪ ɑr nɑt jɔr ˈɛnəmi/","vi":"Họ không phải là kẻ thù của bạn."},{"start":188.84,"end":190.44,"text":"They are your teacher.","words":[["They",188.84],["are",189.04],["your",189.16],["teacher.",189.32]],"ipa":"/ðeɪ ɑr jɔr ˈtitʃər/","vi":"Họ là giáo viên của bạn."},{"start":190.44,"end":194.6,"text":"Starting early also helps you learn faster.","words":[["Starting",190.44],["early",191],["also",191.48],["helps",192.6],["you",193],["learn",193.16],["faster.",193.48]],"ipa":"/ˈstɑrtɪŋ ˈɝli ˈɔlsoʊ hɛlps ju lɝn ˈfæstər/","vi":"Bắt đầu sớm cũng giúp bạn học nhanh hơn."},{"start":194.6,"end":197.96,"text":"When you begin, you get real experience.","words":[["When",194.6],["you",194.84],["begin,",194.96],["you",195.92],["get",196.08],["real",196.4],["experience.",196.64]],"ipa":"/wɛn ju bɪˈɡɪn ju ɡɛt ril ɪkˈspɪriəns/","vi":"Khi bạn bắt đầu, bạn sẽ có được trải nghiệm thực tế."},{"start":197.96,"end":201.36,"text":"You see what works and what does not work.","words":[["You",197.96],["see",198.24],["what",198.56],["works",198.8],["and",199.6],["what",199.8],["does",199.92],["not",200.12],["work.",200.44]],"ipa":"/ju si wʌt wɝks ənd wʌt dʌz nɑt wɝk/","vi":"Bạn thấy những gì hiệu quả và những gì không hiệu quả."},{"start":201.36,"end":203.84,"text":"You understand your problem better.","words":[["You",201.36],["understand",201.6],["your",202.36],["problem",202.48],["better.",202.96]],"ipa":"/ju ˌʌndərˈstænd jɔr ˈprɑbləm ˈbɛtər/","vi":"Bạn hiểu rõ vấn đề của mình hơn."},{"start":203.84,"end":207.36,"text":"You can change your plan and improve.","words":[["You",203.84],["can",204.04],["change",204.24],["your",204.64],["plan",204.8],["and",205.64],["improve.",206.12]],"ipa":"/ju kæn tʃeɪndʒ jɔr plæn ənd ˌɪmˈpruv/","vi":"Bạn có thể thay đổi kế hoạch của mình và cải thiện."},{"start":207.36,"end":211.68,"text":"If you only think and plan, you stay in your head.","words":[["If",207.36],["you",207.52],["only",207.8],["think",208.24],["and",208.76],["plan,",208.92],["you",209.96],["stay",210.16],["in",210.52],["your",210.64],["head.",210.8]],"ipa":"/ɪf ju ˈoʊnli θɪŋk ənd plæn ju steɪ ɪn jɔr hɛd/","vi":"Nếu bạn chỉ suy nghĩ và lập kế hoạch, bạn sẽ ở trong đầu mình."},{"start":211.68,"end":213.96,"text":"You do not see the real world.","words":[["You",211.68],["do",211.84],["not",212.04],["see",212.36],["the",212.56],["real",212.72],["world.",213.04]],"ipa":"/ju du nɑt si ðə ril wɝld/","vi":"Bạn không nhìn thấy thế giới thực."},{"start":213.96,"end":215.64,"text":"You do not grow.","words":[["You",213.96],["do",214.16],["not",214.36],["grow.",214.68]],"ipa":"/ju du nɑt ɡroʊ/","vi":"Bạn không phát triển."},{"start":215.64,"end":218.4,"text":"Action gives you real lessons.","words":[["Action",215.64],["gives",216.24],["you",216.6],["real",216.84],["lessons.",217.12]],"ipa":"/ˈækʃən ɡɪvz ju ril ˈlɛsənz/","vi":"Hành động mang lại cho bạn những bài học thực sự."},{"start":218.4,"end":221.44,"text":"And these lessons are very valuable.","words":[["And",218.4],["these",218.6],["lessons",218.92],["are",219.56],["very",219.8],["valuable.",220.2]],"ipa":"/ənd ðiz ˈlɛsənz ɑr ˈvɛri ˈvæljəbəl/","vi":"Và những bài học này rất có giá trị."},{"start":221.44,"end":224.52,"text":"They help you become better every day.","words":[["They",221.44],["help",221.6],["you",221.92],["become",222.04],["better",222.56],["every",223.28],["day.",223.64]],"ipa":"/ðeɪ hɛlp ju bɪˈkʌm ˈbɛtər ˈɛvəri deɪ/","vi":"Họ giúp bạn trở nên tốt hơn mỗi ngày."},{"start":224.52,"end":228.64,"text":"Sometimes, people compare themselves to others.","words":[["Sometimes,",224.52],["people",225.72],["compare",226.08],["themselves",226.56],["to",227.28],["others.",227.48]],"ipa":"/səmˈtaɪmz ˈpipəl kəmˈpɛr ðɛmˈsɛlvz tu ˈʌðərz/","vi":"Đôi khi, người ta so sánh mình với người khác."},{"start":228.64,"end":231.28,"text":"They see someone who is very good.","words":[["They",228.64],["see",228.84],["someone",229.2],["who",229.64],["is",229.84],["very",230],["good.",230.36]],"ipa":"/ðeɪ si ˈsʌmˌwʌn hu ɪz ˈvɛri ɡʊd/","vi":"Họ thấy một người rất tốt."},{"start":231.28,"end":235,"text":"They think, \\"I can never be like that.\\"","words":[["They",231.28],["think,",231.52],["\\"I",232.72],["can",232.96],["never",233.28],["be",233.64],["like",233.8],["that.\\"",234.08]],"ipa":"/ðeɪ θɪŋk aɪ kæn ˈnɛvər bi laɪk ðæt/","vi":"Họ nghĩ: “Tôi không bao giờ có thể như vậy được”."},{"start":235,"end":237.44,"text":"But they forget something important.","words":[["But",235],["they",235.24],["forget",235.44],["something",235.92],["important.",236.32]],"ipa":"/bʌt ðeɪ fərˈɡɛt ˈsʌmθɪŋ ˌɪmˈpɔrtənt/","vi":"Nhưng họ quên mất một điều quan trọng."},{"start":237.44,"end":240.44,"text":"That person also started at zero.","words":[["That",237.44],["person",237.68],["also",238.2],["started",238.68],["at",239.16],["zero.",239.36]],"ipa":"/ðæt ˈpɝsən ˈɔlsoʊ ˈstɑrtɪd æt ˈzɪroʊ/","vi":"Người đó cũng bắt đầu từ con số 0."},{"start":240.44,"end":243.16,"text":"That person was also a beginner.","words":[["That",240.44],["person",240.72],["was",241.16],["also",241.4],["a",241.92],["beginner.",242]],"ipa":"/ðæt ˈpɝsən wɑz ˈɔlsoʊ ə bɪˈɡɪnər/","vi":"Người đó cũng là người mới bắt đầu."},{"start":243.16,"end":246.56,"text":"That person also made many mistakes.","words":[["That",243.16],["person",243.44],["also",243.88],["made",244.4],["many",244.88],["mistakes.",245.32]],"ipa":"/ðæt ˈpɝsən ˈɔlsoʊ meɪd ˈmɛni mɪˈsteɪks/","vi":"Người đó cũng mắc nhiều sai lầm."},{"start":246.56,"end":249.04,"text":"You only see their success now.","words":[["You",246.56],["only",246.76],["see",247.08],["their",247.36],["success",247.56],["now.",248.08]],"ipa":"/ju ˈoʊnli si ðɛr səkˈsɛs naʊ/","vi":"Bây giờ bạn chỉ thấy thành công của họ."},{"start":249.04,"end":251.68,"text":"You do not see their past.","words":[["You",249.04],["do",249.24],["not",249.56],["see",249.92],["their",250.16],["past.",250.4]],"ipa":"/ju du nɑt si ðɛr pæst/","vi":"Bạn không nhìn thấy quá khứ của họ."},{"start":251.68,"end":256.88,"text":"So, do not compare your beginning to someone else's middle or end.","words":[["So,",251.68],["do",252.36],["not",252.6],["compare",252.88],["your",253.32],["beginning",253.44],["to",253.96],["someone",254.12],["else's",254.56],["middle",255],["or",255.52],["end.",256]],"ipa":"/soʊ du nɑt kəmˈpɛr jɔr bɪˈɡɪnɪŋ tu ˈsʌmˌwʌn ˈɛlsɪz ˈmɪdəl ɔr ɛnd/","vi":"Vì vậy, đừng so sánh phần mở đầu của bạn với phần giữa hoặc phần cuối của người khác."},{"start":256.88,"end":259.04,"text":"Focus on your own path.","words":[["Focus",256.88],["on",257.4],["your",257.52],["own",257.72],["path.",257.96]],"ipa":"/ˈfoʊkəs ɑn jɔr oʊn pæθ/","vi":"Hãy tập trung vào con đường của riêng bạn."},{"start":259.04,"end":261.64,"text":"Focus on your own progress.","words":[["Focus",259.04],["on",259.64],["your",259.8],["own",260.04],["progress.",260.28]],"ipa":"/ˈfoʊkəs ɑn jɔr oʊn ˈprɑˌɡrɛs/","vi":"Tập trung vào sự tiến bộ của riêng bạn."},{"start":261.64,"end":264.44,"text":"Every small step is important.","words":[["Every",261.64],["small",262.08],["step",262.64],["is",263.12],["important.",263.32]],"ipa":"/ˈɛvəri smɔl stɛp ɪz ˌɪmˈpɔrtənt/","vi":"Mỗi bước nhỏ đều quan trọng."},{"start":264.44,"end":266.6,"text":"There is also another problem.","words":[["There",264.44],["is",264.64],["also",264.88],["another",265.24],["problem.",265.6]],"ipa":"/ðɛr ɪz ˈɔlsoʊ əˈnʌðər ˈprɑbləm/","vi":"Ngoài ra còn có một vấn đề khác."},{"start":266.6,"end":270.04,"text":"Many people want to know everything before they start.","words":[["Many",266.6],["people",266.88],["want",267.24],["to",267.44],["know",267.52],["everything",267.8],["before",268.52],["they",268.92],["start.",269.08]],"ipa":"/ˈmɛni ˈpipəl wɑnt tu noʊ ˈɛvriˌθɪŋ bɪˈfɔr ðeɪ stɑrt/","vi":"Nhiều người muốn biết mọi thứ trước khi bắt đầu."},{"start":270.04,"end":272.24,"text":"They want the perfect plan.","words":[["They",270.04],["want",270.24],["the",270.52],["perfect",270.64],["plan.",271.24]],"ipa":"/ðeɪ wɑnt ðə pərˈfɛkt plæn/","vi":"Họ muốn một kế hoạch hoàn hảo."},{"start":272.24,"end":274.32,"text":"They want all the answers.","words":[["They",272.24],["want",272.44],["all",272.76],["the",272.92],["answers.",273.12]],"ipa":"/ðeɪ wɑnt ɔl ðə ˈænsərz/","vi":"Họ muốn tất cả các câu trả lời."},{"start":274.32,"end":276.96,"text":"But life does not work like that.","words":[["But",274.32],["life",274.56],["does",274.96],["not",275.2],["work",275.52],["like",275.8],["that.",276.08]],"ipa":"/bʌt laɪf dʌz nɑt wɝk laɪk ðæt/","vi":"Nhưng cuộc sống không diễn ra như vậy."},{"start":276.96,"end":280.28,"text":"You cannot know everything in the beginning.","words":[["You",276.96],["cannot",277.16],["know",277.76],["everything",278.2],["in",278.84],["the",278.96],["beginning.",279.04]],"ipa":"/ju ˈkænɑt noʊ ˈɛvriˌθɪŋ ɪn ðə bɪˈɡɪnɪŋ/","vi":"Bạn không thể biết mọi thứ ngay từ đầu."},{"start":280.28,"end":284.48,"text":"Some things become clear only when you move forward.","words":[["Some",280.28],["things",280.6],["become",280.96],["clear",281.48],["only",282.04],["when",282.8],["you",282.96],["move",283.08],["forward.",283.4]],"ipa":"/sʌm θɪŋz bɪˈkʌm klɪr ˈoʊnli wɛn ju muv ˈfɔrwərd/","vi":"Một số điều chỉ trở nên rõ ràng khi bạn tiến về phía trước."},{"start":284.48,"end":287.96,"text":"It is like walking in the dark small light.","words":[["It",284.48],["is",284.64],["like",284.8],["walking",285.16],["in",285.64],["the",285.76],["dark",285.88],["small",286.64],["light.",287.12]],"ipa":"/ɪt ɪz laɪk ˈwɔkɪŋ ɪn ðə dɑrk smɔl laɪt/","vi":"Nó giống như đi trong bóng tối nhỏ ánh sáng."},{"start":287.96,"end":292.76,"text":"You cannot see the whole road, but you can see the next step.","words":[["You",287.96],["cannot",288.12],["see",288.68],["the",289],["whole",289.12],["road,",289.44],["but",290.4],["you",290.72],["can",290.84],["see",291.04],["the",291.28],["next",291.44],["step.",291.76]],"ipa":"/ju ˈkænɑt si ðə hoʊl roʊd bʌt ju kæn si ðə nɛkst stɛp/","vi":"Bạn không thể nhìn thấy toàn bộ con đường, nhưng bạn có thể nhìn thấy bước tiếp theo."},{"start":292.76,"end":294.88,"text":"And that is enough.","words":[["And",292.76],["that",293.32],["is",293.6],["enough.",293.76]],"ipa":"/ənd ðæt ɪz ɪˈnʌf/","vi":"Và thế là đủ."},{"start":294.88,"end":298.72,"text":"When you take that step, you will see the next one.","words":[["When",294.88],["you",295.08],["take",295.24],["that",295.6],["step,",295.88],["you",296.6],["will",296.76],["see",296.96],["the",297.28],["next",297.4],["one.",297.84]],"ipa":"/wɛn ju teɪk ðæt stɛp ju wɪl si ðə nɛkst wʌn/","vi":"Khi bạn thực hiện bước đó, bạn sẽ thấy bước tiếp theo."},{"start":298.72,"end":301.96,"text":"Step by step, you will reach your goal.","words":[["Step",298.72],["by",299.08],["step,",299.28],["you",300.2],["will",300.36],["reach",300.56],["your",300.84],["goal.",300.96]],"ipa":"/stɛp baɪ stɛp ju wɪl ritʃ jɔr ɡoʊl/","vi":"Từng bước một, bạn sẽ đạt được mục tiêu của mình."},{"start":301.96,"end":305.96,"text":"Fear is a big reason why people do not start.","words":[["Fear",301.96],["is",302.52],["a",302.92],["big",303],["reason",303.36],["why",303.8],["people",304.04],["do",304.44],["not",304.6],["start.",304.92]],"ipa":"/fɪr ɪz ə bɪɡ ˈrizən waɪ ˈpipəl du nɑt stɑrt/","vi":"Sợ hãi là lý do lớn khiến mọi người không bắt đầu."},{"start":305.96,"end":307.72,"text":"Fear of failure.","words":[["Fear",305.96],["of",306.36],["failure.",306.52]],"ipa":"/fɪr ʌv ˈfeɪljər/","vi":"Sợ thất bại."},{"start":307.72,"end":309.6,"text":"Fear of judgment.","words":[["Fear",307.72],["of",308.08],["judgment.",308.24]],"ipa":"/fɪr ʌv ˈdʒʌdʒmənt/","vi":"Sợ bị phán xét."},{"start":309.6,"end":311.76,"text":"Fear of the unknown.","words":[["Fear",309.6],["of",310.16],["the",310.32],["unknown.",310.52]],"ipa":"/fɪr ʌv ðə ənˈnoʊn/","vi":"Sợ những điều chưa biết."},{"start":311.76,"end":316.44,"text":"These fears are strong, but they are not always true.","words":[["These",311.76],["fears",312.16],["are",312.68],["strong,",312.84],["but",314.08],["they",314.28],["are",314.48],["not",314.56],["always",315.04],["true.",315.52]],"ipa":"/ðiz fɪrz ɑr strɔŋ bʌt ðeɪ ɑr nɑt ˈɔlˌweɪz tru/","vi":"Những nỗi sợ hãi này rất mạnh mẽ, nhưng chúng không phải lúc nào cũng đúng."},{"start":316.44,"end":320.16,"text":"Your mind may create many bad stories.","words":[["Your",316.44],["mind",316.76],["may",317.36],["create",317.6],["many",318.16],["bad",318.56],["stories.",318.92]],"ipa":"/jɔr maɪnd meɪ kriˈeɪt ˈmɛni bæd ˈstɔriz/","vi":"Tâm trí của bạn có thể tạo ra nhiều câu chuyện tồi tệ."},{"start":320.16,"end":323.52,"text":"It may say, \\"People will laugh at you.\\"","words":[["It",320.16],["may",320.36],["say,",320.6],["\\"People",321.68],["will",322.08],["laugh",322.24],["at",322.6],["you.\\"",322.72]],"ipa":"/ɪt meɪ seɪ ˈpipəl wɪl læf æt ju/","vi":"Nó có thể nói, \\"Mọi người sẽ cười nhạo bạn.\\""},{"start":323.52,"end":326.68,"text":"It may say, \\"You will fail.\\"","words":[["It",323.52],["may",323.72],["say,",324],["\\"You",325.04],["will",325.2],["fail.\\"",325.4]],"ipa":"/ɪt meɪ seɪ ju wɪl feɪl/","vi":"Nó có thể nói, \\"Bạn sẽ thất bại.\\""},{"start":326.68,"end":329.96,"text":"But often, these things do not happen.","words":[["But",326.68],["often,",326.92],["these",327.84],["things",328.16],["do",328.52],["not",328.68],["happen.",328.92]],"ipa":"/bʌt ˈɔfən ðiz θɪŋz du nɑt ˈhæpən/","vi":"Nhưng thường thì những điều này không xảy ra."},{"start":329.96,"end":333.2,"text":"And even if they do, it is not the end.","words":[["And",329.96],["even",330.36],["if",330.68],["they",330.84],["do,",331],["it",331.4],["is",331.56],["not",331.72],["the",332.08],["end.",332.28]],"ipa":"/ənd ˈivɪn ɪf ðeɪ du ɪt ɪz nɑt ðə ɛnd/","vi":"Và ngay cả khi họ làm vậy, đó vẫn chưa phải là kết thúc."},{"start":333.2,"end":334.84,"text":"You can try again.","words":[["You",333.2],["can",333.36],["try",333.52],["again.",333.84]],"ipa":"/ju kæn traɪ əˈɡɛn/","vi":"Bạn có thể thử lại."},{"start":334.84,"end":337.36,"text":"You can learn and improve.","words":[["You",334.84],["can",335],["learn",335.24],["and",335.76],["improve.",336]],"ipa":"/ju kæn lɝn ənd ˌɪmˈpruv/","vi":"Bạn có thể học hỏi và cải thiện."},{"start":337.36,"end":340.76,"text":"Fear becomes smaller when you face it.","words":[["Fear",337.36],["becomes",337.72],["smaller",338.36],["when",339.32],["you",339.48],["face",339.64],["it.",340.04]],"ipa":"/fɪr bɪˈkʌmz ˈsmɔlər wɛn ju feɪs ɪt/","vi":"Nỗi sợ hãi sẽ nhỏ đi khi bạn đối mặt với nó."},{"start":340.76,"end":344,"text":"But it becomes bigger when you run away from it.","words":[["But",340.76],["it",340.96],["becomes",341.08],["bigger",341.64],["when",342.08],["you",342.28],["run",342.44],["away",342.68],["from",343.04],["it.",343.32]],"ipa":"/bʌt ɪt bɪˈkʌmz ˈbɪɡər wɛn ju rʌn əˈweɪ frʌm ɪt/","vi":"Nhưng nó sẽ trở nên lớn hơn khi bạn chạy trốn khỏi nó."},{"start":344,"end":348.12,"text":"Starting before you are ready also builds discipline.","words":[["Starting",344],["before",344.56],["you",345],["are",345.2],["ready",345.44],["also",346],["builds",346.44],["discipline.",346.92]],"ipa":"/ˈstɑrtɪŋ bɪˈfɔr ju ɑr ˈrɛdi ˈɔlsoʊ bɪldz ˈdɪsəplən/","vi":"Bắt đầu trước khi bạn sẵn sàng cũng giúp xây dựng tính kỷ luật."},{"start":348.12,"end":352.6,"text":"Discipline means you do something even when you do not feel like it.","words":[["Discipline",348.12],["means",348.8],["you",349.12],["do",349.28],["something",349.56],["even",350.08],["when",350.48],["you",350.68],["do",350.8],["not",351],["feel",351.32],["like",351.6],["it.",351.92]],"ipa":"/ˈdɪsəplən minz ju du ˈsʌmθɪŋ ˈivɪn wɛn ju du nɑt fil laɪk ɪt/","vi":"Kỷ luật có nghĩa là bạn làm điều gì đó ngay cả khi bạn không cảm thấy thích."},{"start":352.6,"end":355.96,"text":"It means you take action even when it is hard.","words":[["It",352.6],["means",352.72],["you",353.04],["take",353.2],["action",353.6],["even",354.28],["when",354.64],["it",354.8],["is",354.92],["hard.",355.04]],"ipa":"/ɪt minz ju teɪk ˈækʃən ˈivɪn wɛn ɪt ɪz hɑrd/","vi":"Nó có nghĩa là bạn phải hành động ngay cả khi khó khăn."},{"start":355.96,"end":362.96,"text":"This is very powerful because in life, you will not always feel motivated.","words":[["This",355.96],["is",356.28],["very",356.52],["powerful",357.04],["because",358.36],["in",358.76],["life,",358.92],["you",360.04],["will",360.2],["not",360.36],["always",360.8],["feel",361.32],["motivated.",361.64]],"ipa":"/ðɪs ɪz ˈvɛri ˈpaʊərfəl bɪˈkɔz ɪn laɪf ju wɪl nɑt ˈɔlˌweɪz fil ˈmoʊtəˌveɪtəd/","vi":"Điều này rất có tác dụng vì trong cuộc sống, không phải lúc nào bạn cũng cảm thấy có động lực."},{"start":362.96,"end":365.88,"text":"Some days, you will feel tired.","words":[["Some",362.96],["days,",363.28],["you",364],["will",364.12],["feel",364.28],["tired.",364.64]],"ipa":"/sʌm deɪz ju wɪl fil ˈtaɪərd/","vi":"Một số ngày, bạn sẽ cảm thấy mệt mỏi."},{"start":365.88,"end":368.6,"text":"Some days, you will feel lazy.","words":[["Some",365.88],["days,",366.24],["you",366.72],["will",366.84],["feel",367.04],["lazy.",367.44]],"ipa":"/sʌm deɪz ju wɪl fil ˈleɪzi/","vi":"Một số ngày, bạn sẽ cảm thấy lười biếng."},{"start":368.6,"end":373.28,"text":"If you only act when you feel good, you will not go far.","words":[["If",368.6],["you",368.8],["only",369.08],["act",369.48],["when",369.92],["you",370.08],["feel",370.2],["good,",370.56],["you",371.52],["will",371.72],["not",371.84],["go",372.16],["far.",372.36]],"ipa":"/ɪf ju ˈoʊnli ækt wɛn ju fil ɡʊd ju wɪl nɑt ɡoʊ fɑr/","vi":"Nếu bạn chỉ hành động khi cảm thấy thoải mái thì bạn sẽ không thể tiến xa được."},{"start":373.28,"end":376.84,"text":"But if you have discipline, you will keep going.","words":[["But",373.28],["if",373.6],["you",373.76],["have",373.92],["discipline,",374.2],["you",375.24],["will",375.4],["keep",375.56],["going.",375.84]],"ipa":"/bʌt ɪf ju hæv ˈdɪsəplən ju wɪl kip ˈɡoʊɪŋ/","vi":"Nhưng nếu bạn có kỷ luật, bạn sẽ tiếp tục."},{"start":376.84,"end":379.84,"text":"And this will help you reach your goals.","words":[["And",376.84],["this",377.44],["will",377.72],["help",377.84],["you",378.12],["reach",378.28],["your",378.56],["goals.",378.68]],"ipa":"/ənd ðɪs wɪl hɛlp ju ritʃ jɔr ɡoʊlz/","vi":"Và điều này sẽ giúp bạn đạt được mục tiêu của mình."},{"start":379.84,"end":384.6,"text":"Another good thing about starting early is that you create momentum.","words":[["Another",379.84],["good",380.2],["thing",380.44],["about",380.64],["starting",381],["early",381.48],["is",382.36],["that",382.56],["you",382.76],["create",382.88],["momentum.",383.36]],"ipa":"/əˈnʌðər ɡʊd θɪŋ əˈbaʊt ˈstɑrtɪŋ ˈɝli ɪz ðæt ju kriˈeɪt moʊˈmɛntəm/","vi":"Một điều tốt nữa khi bắt đầu sớm là bạn tạo được động lực."},{"start":384.6,"end":388.68,"text":"Momentum is like a small ball that starts to roll.","words":[["Momentum",384.6],["is",385.52],["like",385.72],["a",385.92],["small",386],["ball",386.52],["that",386.88],["starts",387.12],["to",387.56],["roll.",387.72]],"ipa":"/moʊˈmɛntəm ɪz laɪk ə smɔl bɔl ðæt stɑrts tu roʊl/","vi":"Động lượng giống như một quả bóng nhỏ bắt đầu lăn."},{"start":388.68,"end":391.28,"text":"At first, it moves slowly.","words":[["At",388.68],["first,",388.92],["it",389.44],["moves",389.6],["slowly.",390.08]],"ipa":"/æt fɝst ɪt muvz ˈsloʊli/","vi":"Lúc đầu, nó di chuyển chậm."},{"start":391.28,"end":396.4,"text":"But as it goes, it becomes faster and stronger.","words":[["But",391.28],["as",391.68],["it",391.88],["goes,",392],["it",393.16],["becomes",393.28],["faster",393.84],["and",394.88],["stronger.",395.16]],"ipa":"/bʌt æz ɪt ɡoʊz ɪt bɪˈkʌmz ˈfæstər ənd ˈstrɔŋər/","vi":"Nhưng càng đi, nó càng nhanh và mạnh hơn."},{"start":396.4,"end":399,"text":"The same is true for your actions.","words":[["The",396.4],["same",396.56],["is",396.96],["true",397.16],["for",397.48],["your",397.64],["actions.",397.8]],"ipa":"/ðə seɪm ɪz tru fɔr jɔr ˈækʃənz/","vi":"Điều này cũng đúng với hành động của bạn."},{"start":399,"end":404,"text":"When you take one step, it becomes easier to take the next step.","words":[["When",399],["you",399.2],["take",399.32],["one",399.72],["step,",400.04],["it",401.16],["becomes",401.32],["easier",401.92],["to",402.36],["take",402.52],["the",402.76],["next",402.84],["step.",403.16]],"ipa":"/wɛn ju teɪk wʌn stɛp ɪt bɪˈkʌmz ˈiziər tu teɪk ðə nɛkst stɛp/","vi":"Khi bạn thực hiện một bước, việc thực hiện bước tiếp theo sẽ trở nên dễ dàng hơn."},{"start":404,"end":405.64,"text":"You build a habit.","words":[["You",404],["build",404.24],["a",404.52],["habit.",404.6]],"ipa":"/ju bɪld ə ˈhæbət/","vi":"Bạn xây dựng một thói quen."},{"start":405.64,"end":407.64,"text":"You feel progress.","words":[["You",405.64],["feel",405.88],["progress.",406.28]],"ipa":"/ju fil ˈprɑˌɡrɛs/","vi":"Bạn cảm thấy sự tiến bộ."},{"start":407.64,"end":410.04,"text":"And this makes you want to continue.","words":[["And",407.64],["this",407.88],["makes",408.12],["you",408.44],["want",408.52],["to",408.72],["continue.",408.8]],"ipa":"/ənd ðɪs meɪks ju wɑnt tu kənˈtɪnju/","vi":"Và điều này khiến bạn muốn tiếp tục."},{"start":410.04,"end":413.64,"text":"But if you never start, there is no movement.","words":[["But",410.04],["if",410.24],["you",410.4],["never",410.56],["start,",410.92],["there",411.76],["is",411.96],["no",412.16],["movement.",412.48]],"ipa":"/bʌt ɪf ju ˈnɛvər stɑrt ðɛr ɪz noʊ ˈmuvmənt/","vi":"Nhưng nếu bạn không bao giờ bắt đầu, sẽ không có chuyển động."},{"start":413.64,"end":415.76,"text":"There is no energy.","words":[["There",413.64],["is",413.92],["no",414.24],["energy.",414.6]],"ipa":"/ðɛr ɪz noʊ ˈɛnərdʒi/","vi":"Không có năng lượng."},{"start":415.76,"end":419.24,"text":"You may ask, \\"What if I fail?\\"","words":[["You",415.76],["may",415.92],["ask,",416.2],["\\"What",417.2],["if",417.36],["I",417.56],["fail?\\"",417.72]],"ipa":"/ju meɪ æsk wʌt ɪf aɪ feɪl/","vi":"Bạn có thể hỏi, \\"Nếu tôi thất bại thì sao?\\""},{"start":419.24,"end":421.24,"text":"This is a common question.","words":[["This",419.24],["is",419.52],["a",419.64],["common",419.72],["question.",420.12]],"ipa":"/ðɪs ɪz ə ˈkɑmən ˈkwɛstʃən/","vi":"Đây là một câu hỏi phổ biến."},{"start":421.24,"end":424.68,"text":"But failure is not the opposite of success.","words":[["But",421.24],["failure",421.52],["is",422.16],["not",422.4],["the",422.68],["opposite",422.84],["of",423.36],["success.",423.48]],"ipa":"/bʌt ˈfeɪljər ɪz nɑt ðə ˈɑpəzət ʌv səkˈsɛs/","vi":"Nhưng thất bại không phải là đối nghịch của thành công."},{"start":424.68,"end":426.6,"text":"It is part of success.","words":[["It",424.68],["is",424.84],["part",425],["of",425.28],["success.",425.36]],"ipa":"/ɪt ɪz pɑrt ʌv səkˈsɛs/","vi":"Đó là một phần của thành công."},{"start":426.6,"end":430.68,"text":"Every successful person has failed many times.","words":[["Every",426.6],["successful",426.96],["person",427.68],["has",428.28],["failed",428.64],["many",429.12],["times.",429.44]],"ipa":"/ˈɛvəri səkˈsɛsfəl ˈpɝsən hæz feɪld ˈmɛni taɪmz/","vi":"Người thành công nào cũng từng thất bại nhiều lần."},{"start":430.68,"end":433.64,"text":"Failure shows you what does not work.","words":[["Failure",430.68],["shows",431.24],["you",431.8],["what",431.96],["does",432.16],["not",432.32],["work.",432.72]],"ipa":"/ˈfeɪljər ʃoʊz ju wʌt dʌz nɑt wɝk/","vi":"Thất bại cho bạn thấy điều gì không hiệu quả."},{"start":433.64,"end":436.44,"text":"It teaches you valuable lessons.","words":[["It",433.64],["teaches",433.88],["you",434.44],["valuable",434.6],["lessons.",435.2]],"ipa":"/ɪt ˈtitʃəz ju ˈvæljəbəl ˈlɛsənz/","vi":"Nó dạy cho bạn những bài học quý giá."},{"start":436.44,"end":438.44,"text":"It makes you stronger.","words":[["It",436.44],["makes",436.68],["you",437.08],["stronger.",437.2]],"ipa":"/ɪt meɪks ju ˈstrɔŋər/","vi":"Nó làm cho bạn mạnh mẽ hơn."},{"start":438.44,"end":440.2,"text":"It helps you grow.","words":[["It",438.44],["helps",438.64],["you",439],["grow.",439.16]],"ipa":"/ɪt hɛlps ju ɡroʊ/","vi":"Nó giúp bạn phát triển."},{"start":440.2,"end":443.52,"text":"So, do not be afraid of failure.","words":[["So,",440.2],["do",441.2],["not",441.44],["be",441.76],["afraid",441.88],["of",442.32],["failure.",442.44]],"ipa":"/soʊ du nɑt bi əˈfreɪd ʌv ˈfeɪljər/","vi":"Vì vậy, đừng sợ thất bại."},{"start":443.52,"end":450.64,"text":"Be afraid of not trying because if you do not try, you will never know what you can do.","words":[["Be",443.52],["afraid",443.68],["of",444.32],["not",444.48],["trying",444.8],["because",445.92],["if",446.44],["you",446.64],["do",446.76],["not",446.96],["try,",447.28],["you",448.32],["will",448.52],["never",448.68],["know",449.04],["what",449.28],["you",449.44],["can",449.56],["do.",449.76]],"ipa":"/bi əˈfreɪd ʌv nɑt ˈtraɪɪŋ bɪˈkɔz ɪf ju du nɑt traɪ ju wɪl ˈnɛvər noʊ wʌt ju kæn du/","vi":"Đừng sợ không cố gắng vì nếu không thử, bạn sẽ không bao giờ biết mình có thể làm được gì."},{"start":450.64,"end":453.64,"text":"Time is also very important.","words":[["Time",450.64],["is",451.12],["also",451.28],["very",452.12],["important.",452.56]],"ipa":"/taɪm ɪz ˈɔlsoʊ ˈvɛri ˌɪmˈpɔrtənt/","vi":"Thời gian cũng rất quan trọng."},{"start":453.64,"end":455.8,"text":"Time does not wait for you.","words":[["Time",453.64],["does",454],["not",454.16],["wait",454.52],["for",454.8],["you.",455]],"ipa":"/taɪm dʌz nɑt weɪt fɔr ju/","vi":"Thời gian không chờ đợi bạn."},{"start":455.8,"end":459.4,"text":"Every day, you have 24 hours.","words":[["Every",455.8],["day,",456.12],["you",457],["have",457.16],["24",457.48],["hours.",458.2]],"ipa":"/ˈɛvəri deɪ ju hæv ˈaʊərz/","vi":"Mỗi ngày, bạn có 24 giờ."},{"start":459.4,"end":462.76,"text":"How you use your time will shape your future.","words":[["How",459.4],["you",459.68],["use",459.92],["your",460.32],["time",460.48],["will",460.92],["shape",461.08],["your",461.52],["future.",461.68]],"ipa":"/haʊ ju jus jɔr taɪm wɪl ʃeɪp jɔr ˈfjutʃər/","vi":"Cách bạn sử dụng thời gian sẽ định hình tương lai của bạn."},{"start":462.76,"end":467.16,"text":"If you wait too long, you may lose many chances.","words":[["If",462.76],["you",462.96],["wait",463.08],["too",463.36],["long,",463.52],["you",464.52],["may",464.68],["lose",464.96],["many",465.48],["chances.",465.84]],"ipa":"/ɪf ju weɪt tu lɔŋ ju meɪ luz ˈmɛni ˈtʃænsəz/","vi":"Nếu bạn chờ đợi quá lâu, bạn có thể mất nhiều cơ hội."},{"start":467.16,"end":472.56,"text":"But if you start now, even with small steps, you use your time well.","words":[["But",467.16],["if",467.32],["you",467.48],["start",467.6],["now,",468],["even",468.44],["with",468.8],["small",469.08],["steps,",469.52],["you",470.48],["use",470.72],["your",471.04],["time",471.2],["well.",471.6]],"ipa":"/bʌt ɪf ju stɑrt naʊ ˈivɪn wɪð smɔl stɛps ju jus jɔr taɪm wɛl/","vi":"Nhưng nếu bạn bắt đầu ngay bây giờ, ngay cả với những bước nhỏ, bạn sẽ sử dụng tốt thời gian của mình."},{"start":472.56,"end":474.72,"text":"You invest in yourself.","words":[["You",472.56],["invest",472.8],["in",473.44],["yourself.",473.52]],"ipa":"/ju ˌɪnˈvɛst ɪn jərˈsɛlf/","vi":"Bạn đầu tư vào chính mình."},{"start":474.72,"end":477.72,"text":"You build your future little by little.","words":[["You",474.72],["build",474.96],["your",475.36],["future",475.52],["little",476.08],["by",476.44],["little.",476.68]],"ipa":"/ju bɪld jɔr ˈfjutʃər ˈlɪtəl baɪ ˈlɪtəl/","vi":"Bạn xây dựng tương lai của mình từng chút một."},{"start":477.72,"end":481.56,"text":"One day, you will look back and feel proud.","words":[["One",477.72],["day,",478.04],["you",479],["will",479.16],["look",479.28],["back",479.52],["and",480.08],["feel",480.32],["proud.",480.64]],"ipa":"/wʌn deɪ ju wɪl lʊk bæk ənd fil praʊd/","vi":"Một ngày nào đó, bạn sẽ nhìn lại và cảm thấy tự hào."},{"start":481.56,"end":484.16,"text":"You will see how far you have come.","words":[["You",481.56],["will",481.8],["see",481.96],["how",482.28],["far",482.52],["you",482.8],["have",482.92],["come.",483.16]],"ipa":"/ju wɪl si haʊ fɑr ju hæv kʌm/","vi":"Bạn sẽ thấy bạn đã đi được bao xa."},{"start":484.16,"end":488.24,"text":"Sometimes, the idea of starting can feel very big.","words":[["Sometimes,",484.16],["the",484.96],["idea",485.16],["of",485.56],["starting",485.68],["can",486.24],["feel",486.52],["very",486.92],["big.",487.28]],"ipa":"/səmˈtaɪmz ðə aɪˈdiə ʌv ˈstɑrtɪŋ kæn fil ˈvɛri bɪɡ/","vi":"Đôi khi, ý tưởng bắt đầu có thể rất lớn lao."},{"start":488.24,"end":489.96,"text":"It can feel heavy.","words":[["It",488.24],["can",488.4],["feel",488.6],["heavy.",489]],"ipa":"/ɪt kæn fil ˈhɛvi/","vi":"Nó có thể cảm thấy nặng nề."},{"start":489.96,"end":492.16,"text":"But you can make it simple.","words":[["But",489.96],["you",490.28],["can",490.4],["make",490.6],["it",490.88],["simple.",491.04]],"ipa":"/bʌt ju kæn meɪk ɪt ˈsɪmpəl/","vi":"Nhưng bạn có thể làm cho nó đơn giản."},{"start":492.16,"end":494.64,"text":"Do not think about the whole journey.","words":[["Do",492.16],["not",492.4],["think",492.76],["about",492.96],["the",493.28],["whole",493.4],["journey.",493.68]],"ipa":"/du nɑt θɪŋk əˈbaʊt ðə hoʊl ˈdʒɝni/","vi":"Đừng nghĩ về toàn bộ cuộc hành trình."},{"start":494.64,"end":497.2,"text":"Just think about the next step.","words":[["Just",494.64],["think",494.92],["about",495.16],["the",495.72],["next",495.84],["step.",496.2]],"ipa":"/dʒʌst θɪŋk əˈbaʊt ðə nɛkst stɛp/","vi":"Chỉ cần nghĩ về bước tiếp theo."},{"start":497.2,"end":502.36,"text":"Ask yourself, \\"What is one small thing I can do today?\\"","words":[["Ask",497.2],["yourself,",497.64],["\\"What",498.8],["is",499],["one",499.24],["small",499.6],["thing",500.08],["I",500.44],["can",500.56],["do",500.76],["today?\\"",500.96]],"ipa":"/æsk jərˈsɛlf wʌt ɪz wʌn smɔl θɪŋ aɪ kæn du təˈdeɪ/","vi":"Hãy tự hỏi bản thân: “Việc nhỏ nào tôi có thể làm hôm nay?”"},{"start":502.36,"end":503.64,"text":"Then do it.","words":[["Then",502.36],["do",502.68],["it.",502.92]],"ipa":"/ðɛn du ɪt/","vi":"Sau đó làm điều đó."},{"start":503.64,"end":507.64,"text":"It can be very small, but it is enough.","words":[["It",503.64],["can",503.8],["be",503.96],["very",504.12],["small,",504.56],["but",505.72],["it",506.2],["is",506.32],["enough.",506.48]],"ipa":"/ɪt kæn bi ˈvɛri smɔl bʌt ɪt ɪz ɪˈnʌf/","vi":"Nó có thể rất nhỏ, nhưng thế là đủ."},{"start":507.64,"end":514.04,"text":"Small actions done every day can create big change over time.","words":[["Small",507.64],["actions",508.12],["done",509.32],["every",509.88],["day",510.24],["can",511.04],["create",511.36],["big",511.92],["change",512.2],["over",512.8],["time.",513.08]],"ipa":"/smɔl ˈækʃənz dʌn ˈɛvəri deɪ kæn kriˈeɪt bɪɡ tʃeɪndʒ ˈoʊvər taɪm/","vi":"Những hành động nhỏ được thực hiện hàng ngày có thể tạo ra sự thay đổi lớn theo thời gian."},{"start":514.04,"end":516.8,"text":"You also do not need to be perfect.","words":[["You",514.04],["also",514.24],["do",514.64],["not",514.8],["need",515.12],["to",515.4],["be",515.48],["perfect.",515.68]],"ipa":"/ju ˈɔlsoʊ du nɑt nid tu bi pərˈfɛkt/","vi":"Bạn cũng không cần phải hoàn hảo."},{"start":516.8,"end":518.52,"text":"You just need to begin.","words":[["You",516.8],["just",516.96],["need",517.24],["to",517.48],["begin.",517.56]],"ipa":"/ju dʒʌst nid tu bɪˈɡɪn/","vi":"Bạn chỉ cần bắt đầu."},{"start":518.52,"end":522.6,"text":"Many great things in the world started in a simple way.","words":[["Many",518.52],["great",518.92],["things",519.36],["in",519.8],["the",519.92],["world",520.04],["started",520.44],["in",520.92],["a",521.08],["simple",521.16],["way.",521.64]],"ipa":"/ˈmɛni ɡreɪt θɪŋz ɪn ðə wɝld ˈstɑrtɪd ɪn ə ˈsɪmpəl weɪ/","vi":"Nhiều điều tuyệt vời trên thế giới bắt đầu một cách đơn giản."},{"start":522.6,"end":524.28,"text":"A small idea.","words":[["A",522.6],["small",522.72],["idea.",523.24]],"ipa":"/ə smɔl aɪˈdiə/","vi":"Một ý tưởng nhỏ."},{"start":524.28,"end":526.04,"text":"A simple action.","words":[["A",524.28],["simple",524.4],["action.",524.92]],"ipa":"/ə ˈsɪmpəl ˈækʃən/","vi":"Một hành động đơn giản."},{"start":526.04,"end":528.8,"text":"No one is perfect at the beginning.","words":[["No",526.04],["one",526.4],["is",526.6],["perfect",526.84],["at",527.48],["the",527.6],["beginning.",527.72]],"ipa":"/noʊ wʌn ɪz pərˈfɛkt æt ðə bɪˈɡɪnɪŋ/","vi":"Không ai hoàn hảo ngay từ đầu."},{"start":528.8,"end":531.52,"text":"Everyone learns along the way.","words":[["Everyone",528.8],["learns",529.4],["along",530],["the",530.44],["way.",530.56]],"ipa":"/ˈɛvriˌwʌn lɝnz əˈlɔŋ ðə weɪ/","vi":"Mọi người đều học trên đường đi."},{"start":531.52,"end":534.72,"text":"So, give yourself permission to be a beginner.","words":[["So,",531.52],["give",531.92],["yourself",532.2],["permission",532.64],["to",533.28],["be",533.44],["a",533.6],["beginner.",533.64]],"ipa":"/soʊ ɡɪv jərˈsɛlf pərˈmɪʃən tu bi ə bɪˈɡɪnər/","vi":"Vì vậy, hãy cho phép mình là người mới bắt đầu."},{"start":534.72,"end":536.96,"text":"It is okay to be slow.","words":[["It",534.72],["is",534.88],["okay",535.04],["to",535.56],["be",535.68],["slow.",535.84]],"ipa":"/ɪt ɪz ˌoʊˈkeɪ tu bi sloʊ/","vi":"Chậm thôi cũng được."},{"start":536.96,"end":539.48,"text":"It is okay to not know everything.","words":[["It",536.96],["is",537.12],["okay",537.32],["to",537.68],["not",537.84],["know",538.12],["everything.",538.36]],"ipa":"/ɪt ɪz ˌoʊˈkeɪ tu nɑt noʊ ˈɛvriˌθɪŋ/","vi":"Không sao cả khi không biết mọi thứ."},{"start":539.48,"end":542.56,"text":"What matters is that you move forward.","words":[["What",539.48],["matters",539.8],["is",540.76],["that",540.96],["you",541.16],["move",541.28],["forward.",541.56]],"ipa":"/wʌt ˈmætərz ɪz ðæt ju muv ˈfɔrwərd/","vi":"Điều quan trọng là bạn tiến về phía trước."},{"start":542.56,"end":545.6,"text":"Support from others can also help.","words":[["Support",542.56],["from",543.28],["others",543.56],["can",544.12],["also",544.32],["help.",544.72]],"ipa":"/səˈpɔrt frʌm ˈʌðərz kæn ˈɔlsoʊ hɛlp/","vi":"Sự hỗ trợ từ người khác cũng có thể giúp ích."},{"start":545.6,"end":547.48,"text":"You can talk to friends.","words":[["You",545.6],["can",545.76],["talk",545.96],["to",546.28],["friends.",546.4]],"ipa":"/ju kæn tɔk tu frɛndz/","vi":"Bạn có thể nói chuyện với bạn bè."},{"start":547.48,"end":550.92,"text":"You can learn from people who have more experience.","words":[["You",547.48],["can",547.64],["learn",547.88],["from",548.24],["people",548.44],["who",548.84],["have",549.04],["more",549.24],["experience.",549.48]],"ipa":"/ju kæn lɝn frʌm ˈpipəl hu hæv mɔr ɪkˈspɪriəns/","vi":"Bạn có thể học hỏi từ những người có nhiều kinh nghiệm hơn."},{"start":550.92,"end":554,"text":"You can watch, listen, and read.","words":[["You",550.92],["can",551.04],["watch,",551.28],["listen,",552.08],["and",552.76],["read.",553.04]],"ipa":"/ju kæn wɑtʃ ˈlɪsən ənd rɛd/","vi":"Bạn có thể xem, nghe và đọc."},{"start":554,"end":557.64,"text":"But remember, learning is not enough.","words":[["But",554],["remember,",554.36],["learning",555.6],["is",556.12],["not",556.32],["enough.",556.56]],"ipa":"/bʌt rɪˈmɛmbər ˈlɝnɪŋ ɪz nɑt ɪˈnʌf/","vi":"Nhưng hãy nhớ rằng, học thôi là chưa đủ."},{"start":557.64,"end":559.88,"text":"You must also act.","words":[["You",557.64],["must",557.88],["also",558.32],["act.",558.84]],"ipa":"/ju mʌst ˈɔlsoʊ ækt/","vi":"Bạn cũng phải hành động."},{"start":559.88,"end":564.2,"text":"Knowledge without action does not change your life.","words":[["Knowledge",559.88],["without",560.64],["action",561.08],["does",561.96],["not",562.2],["change",562.64],["your",563.04],["life.",563.16]],"ipa":"/ˈnɑlədʒ wɪˈθaʊt ˈækʃən dʌz nɑt tʃeɪndʒ jɔr laɪf/","vi":"Kiến thức không hành động không làm thay đổi cuộc sống của bạn."},{"start":564.2,"end":568,"text":"Action turns knowledge into real results.","words":[["Action",564.2],["turns",564.8],["knowledge",565.24],["into",566.08],["real",566.48],["results.",566.84]],"ipa":"/ˈækʃən tɝnz ˈnɑlədʒ ˈɪntu ril rɪˈzʌlts/","vi":"Hành động biến kiến ​​thức thành kết quả thực sự."},{"start":568,"end":570.64,"text":"Sometimes, you may feel stuck.","words":[["Sometimes,",568],["you",568.84],["may",569],["feel",569.24],["stuck.",569.56]],"ipa":"/səmˈtaɪmz ju meɪ fil stʌk/","vi":"Đôi khi, bạn có thể cảm thấy bế tắc."},{"start":570.64,"end":573.36,"text":"You may feel like you are not improving.","words":[["You",570.64],["may",570.8],["feel",571],["like",571.32],["you",571.56],["are",571.72],["not",571.84],["improving.",572.16]],"ipa":"/ju meɪ fil laɪk ju ɑr nɑt ˌɪmˈpruvɪŋ/","vi":"Bạn có thể cảm thấy như mình không tiến bộ."},{"start":573.36,"end":575.04,"text":"This is normal.","words":[["This",573.36],["is",573.68],["normal.",573.84]],"ipa":"/ðɪs ɪz ˈnɔrməl/","vi":"Điều này là bình thường."},{"start":575.04,"end":578.2,"text":"Progress is not always fast.","words":[["Progress",575.04],["is",575.88],["not",576.12],["always",576.6],["fast.",577.08]],"ipa":"/ˈprɑˌɡrɛs ɪz nɑt ˈɔlˌweɪz fæst/","vi":"Tiến độ không phải lúc nào cũng nhanh."},{"start":578.2,"end":580.4,"text":"Sometimes, it is slow.","words":[["Sometimes,",578.2],["it",579.04],["is",579.16],["slow.",579.36]],"ipa":"/səmˈtaɪmz ɪt ɪz sloʊ/","vi":"Đôi khi, nó chậm."},{"start":580.4,"end":583,"text":"Sometimes, it is hard to see.","words":[["Sometimes,",580.4],["it",581.32],["is",581.48],["hard",581.64],["to",581.96],["see.",582.08]],"ipa":"/səmˈtaɪmz ɪt ɪz hɑrd tu si/","vi":"Đôi khi, thật khó để nhìn thấy."},{"start":583,"end":586.24,"text":"But if you keep going, you will improve.","words":[["But",583],["if",583.16],["you",583.32],["keep",583.48],["going,",583.76],["you",584.68],["will",584.84],["improve.",584.96]],"ipa":"/bʌt ɪf ju kip ˈɡoʊɪŋ ju wɪl ˌɪmˈpruv/","vi":"Nhưng nếu bạn tiếp tục, bạn sẽ tiến bộ."},{"start":586.24,"end":588.12,"text":"Trust the process.","words":[["Trust",586.24],["the",586.68],["process.",586.76]],"ipa":"/trʌst ðə ˈprɑˌsɛs/","vi":"Hãy tin tưởng vào quá trình này."},{"start":588.12,"end":589.84,"text":"Trust your effort.","words":[["Trust",588.12],["your",588.68],["effort.",588.88]],"ipa":"/trʌst jɔr ˈɛfərt/","vi":"Hãy tin tưởng vào nỗ lực của bạn."},{"start":589.84,"end":594.08,"text":"Every step you take is building something inside you.","words":[["Every",589.84],["step",590.2],["you",590.56],["take",590.68],["is",591.4],["building",591.72],["something",592.16],["inside",592.68],["you.",593.36]],"ipa":"/ˈɛvəri stɛp ju teɪk ɪz ˈbɪldɪŋ ˈsʌmθɪŋ ˌɪnˈsaɪd ju/","vi":"Mỗi bước bạn thực hiện đều đang xây dựng một điều gì đó bên trong bạn."},{"start":594.08,"end":597.76,"text":"Starting before where are ready is not easy.","words":[["Starting",594.08],["before",594.6],["where",595],["are",595.16],["ready",595.4],["is",595.92],["not",596.28],["easy.",596.68]],"ipa":"/ˈstɑrtɪŋ bɪˈfɔr wɛr ɑr ˈrɛdi ɪz nɑt ˈizi/","vi":"Bắt đầu trước khi sẵn sàng là điều không hề dễ dàng."},{"start":597.76,"end":599.52,"text":"It takes courage.","words":[["It",597.76],["takes",597.96],["courage.",598.36]],"ipa":"/ɪt teɪks ˈkɝədʒ/","vi":"Cần phải có lòng can đảm."},{"start":599.52,"end":605.44,"text":"It takes effort, but it is worth it because it helps you grow.","words":[["It",599.52],["takes",599.72],["effort,",600.04],["but",601.12],["it",601.48],["is",601.6],["worth",601.84],["it",602.28],["because",603],["it",603.56],["helps",603.76],["you",604.16],["grow.",604.32]],"ipa":"/ɪt teɪks ˈɛfərt bʌt ɪt ɪz wɝθ ɪt bɪˈkɔz ɪt hɛlps ju ɡroʊ/","vi":"Việc này cần nỗ lực nhưng đáng giá vì nó giúp bạn phát triển."},{"start":605.44,"end":607.16,"text":"It helps you learn.","words":[["It",605.44],["helps",605.68],["you",606.04],["learn.",606.2]],"ipa":"/ɪt hɛlps ju lɝn/","vi":"Nó giúp bạn học hỏi."},{"start":607.16,"end":610.64,"text":"It helps you become a better version of yourself.","words":[["It",607.16],["helps",607.36],["you",607.68],["become",607.8],["a",608.4],["better",608.52],["version",608.84],["of",609.28],["yourself.",609.4]],"ipa":"/ɪt hɛlps ju bɪˈkʌm ə ˈbɛtər ˈvɝʒən ʌv jərˈsɛlf/","vi":"Nó giúp bạn trở thành một phiên bản tốt hơn của chính mình."},{"start":610.64,"end":613.68,"text":"When you start, you open new doors.","words":[["When",610.64],["you",610.8],["start,",610.96],["you",611.6],["open",611.88],["new",612.24],["doors.",612.44]],"ipa":"/wɛn ju stɑrt ju ˈoʊpən nu dɔrz/","vi":"Khi bạn bắt đầu, bạn mở ra những cánh cửa mới."},{"start":613.68,"end":616.04,"text":"You create new chances.","words":[["You",613.68],["create",613.84],["new",614.4],["chances.",614.72]],"ipa":"/ju kriˈeɪt nu ˈtʃænsəz/","vi":"Bạn tạo ra những cơ hội mới."},{"start":616.04,"end":618.08,"text":"You change your story.","words":[["You",616.04],["change",616.28],["your",616.72],["story.",616.88]],"ipa":"/ju tʃeɪndʒ jɔr ˈstɔri/","vi":"Bạn thay đổi câu chuyện của bạn."},{"start":618.08,"end":621.32,"text":"So, do not wait for the perfect time.","words":[["So,",618.08],["do",618.76],["not",619],["wait",619.36],["for",619.72],["the",619.84],["perfect",619.96],["time.",620.44]],"ipa":"/soʊ du nɑt weɪt fɔr ðə pərˈfɛkt taɪm/","vi":"Vì vậy, đừng chờ đợi thời điểm hoàn hảo."},{"start":621.32,"end":624.24,"text":"Do not wait until you feel ready.","words":[["Do",621.32],["not",621.52],["wait",621.92],["until",622.32],["you",622.68],["feel",622.84],["ready.",623.28]],"ipa":"/du nɑt weɪt ənˈtɪl ju fil ˈrɛdi/","vi":"Đừng đợi cho đến khi bạn cảm thấy sẵn sàng."},{"start":624.24,"end":629.48,"text":"That day may never come. Start now. Start small.","words":[["That",624.24],["day",624.56],["may",624.88],["never",625.08],["come.",625.4],["Start",626.4],["now.",626.8],["Start",627.8],["small.",628.28]],"ipa":"/ðæt deɪ meɪ ˈnɛvər kʌm stɑrt naʊ stɑrt smɔl/","vi":"Ngày đó có thể không bao giờ đến. Bắt đầu ngay bây giờ. Bắt đầu nhỏ."},{"start":629.48,"end":631.32,"text":"Start where you are.","words":[["Start",629.48],["where",629.84],["you",630.08],["are.",630.32]],"ipa":"/stɑrt wɛr ju ɑr/","vi":"Bắt đầu từ nơi bạn đang ở."},{"start":631.32,"end":633.2,"text":"Use what you have.","words":[["Use",631.32],["what",631.72],["you",631.92],["have.",632.08]],"ipa":"/jus wʌt ju hæv/","vi":"Sử dụng những gì bạn có."},{"start":633.2,"end":636.6,"text":"Take one step, then another.","words":[["Take",633.2],["one",633.6],["step,",634],["then",635.12],["another.",635.52]],"ipa":"/teɪk wʌn stɛp ðɛn əˈnʌðər/","vi":"Bước một bước, rồi bước khác."},{"start":636.6,"end":642.68,"text":"Keep going, and one day you will see that you were ready all along.","words":[["Keep",636.6],["going,",636.92],["and",637.96],["one",638.2],["day",638.48],["you",639.48],["will",639.64],["see",639.84],["that",640.16],["you",640.36],["were",640.48],["ready",640.68],["all",641.16],["along.",641.56]],"ipa":"/kip ˈɡoʊɪŋ ənd wʌn deɪ ju wɪl si ðæt ju wɝ ˈrɛdi ɔl əˈlɔŋ/","vi":"Hãy tiếp tục, và một ngày nào đó bạn sẽ thấy rằng mình đã sẵn sàng."},{"start":642.68,"end":647.86,"text":"You just needed to begin.","words":[["You",642.68],["just",642.84],["needed",643.2],["to",643.56],["begin.",643.64]],"ipa":"/ju dʒʌst ˈnidəd tu bɪˈɡɪn/","vi":"Bạn chỉ cần bắt đầu."}]`),h={id:t,youtubeId:n,title:e,channel:i,level:"A1",duration:648,captions:a,segments:o};export{a as captions,i as channel,h as default,r as duration,t as id,s as level,o as segments,e as title,n as youtubeId};
